erjpeg\" src=\"/assets/0c0d9703901673f36716.jpeg\" width=\"977\" height=\"18\"></a></div><div style=\"text-align: center;\"><a href=\"http://debat.vorespolitikere.dk/konsp.mp3\" target=\"_blank\"><img alt=\"linerjpeg\" src=\"/assets/0c0d9703901673f36716.jpeg\" width=\"977\" height=\"18\"></a></div><div style=\"text-align: center;\"><a href=\"https://debat.verdensbilledet.dk/olebjerg.mp3\" target=\"_blank\"><img alt=\"linerjpeg\" src=\"/assets/0c0d9703901673f36716.jpeg\" width=\"977\" height=\"18\"></a><br></div>\n          \n      </span>\n    </div>\n\n    \n\n</div>"},{"id":"s14","kind":"html","html":"<div id=\"page-zones__main-widgets__644dff1b3fd90\" data-name=\"responsivecolumns\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"PqzmJKqrhcQrbYJ\" data-parentuniqueid=\"RLJB7nUxOF0aaIl\">\n    <div class=\"bk-responsivecolumns responsivecolumns widget__responsivecolumns js-responsivecolumns\">\n\n\n            \n                    <section id=\"page-zones__main-widgets__644dff1b3fd90-zones__644dff1b58eb4\" class=\"bk-zone column columns-three-left\" data-uniqueid=\"kAtr9fwVVB2bxip\" data-parentuniqueid=\"PqzmJKqrhcQrbYJ\">            \n<div id=\"page-zones__main-widgets__644dff1b3fd90-zones__644dff1b58eb4-widgets__644dff1baf406\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"r5aSPLnISqeDXsH\" data-parentuniqueid=\"kAtr9fwVVB2bxip\">\n        <div class=\"bk-content-text content widget__content wysihtml-editor-content\" itemscope itemtype=\"https://schema.org/WebPage\">\n      <span class=\"js-text-content content-block\" itemprop=\"mainContentOfPage\" itemscope itemtype=\"https://schema.org/WebPageElement\">\n\n                    <div style=\"text-align: center;\"><b><span style=\"color: rgb(255, 255, 255);\"><a href=\"https://verdensbilledet.dk/samfundsreligionen#satanist\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\">Denne verdens \"lucifister\" lever for det meste skjult i en blanding af trolddomskraft, jødedom, hedenskab og en passende portion af \"kristen\" symbolik for at få det hele til at se mere respektabelt ud.</span></a></span></b><b><span style=\"color: rgb(255, 255, 255);\"><a href=\"https://verdensbilledet.dk/samfundsreligionen#satanist\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\"> Den vigtigste \"regel\" \"bag facaden\" er ingen regler..! Følg dine følelser, din lyst, dit begær, tag hvad du vil, bliv din egen \"gud\" og bestem selv hvad der er \"godt og ondt\" for dig. Gå skridtet videre end Adam og Eva. Når du har spist af \"Kundskabens Træ\" (kundskab uden fællesskab med Bibelens Gud som din skaber) så ræk hånden ud, spis af \"Livets Træ\" og lev evigt i et samfund uden absolutter &gt;&gt;&gt;</span></a><br></span></b></div>\n          \n      </span>\n    </div>\n\n    \n\n</div>\n    </section>\n            <section id=\"page-zones__main-widgets__644dff1b3fd90-zones__644dff1b611de\" class=\"bk-zone column columns-three-middle\" data-uniqueid=\"uCpfe9NUvDO02ZL\" data-parentuniqueid=\"PqzmJKqrhcQrbYJ\">            \n<div id=\"page-zones__main-widgets__644dff1b3fd90-zones__644dff1b611de-widgets__644dff1b6c024\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"yMscw3BzdPdPdqE\" data-parentuniqueid=\"uCpfe9NUvDO02ZL\">\n        <div class=\"bk-content-text content widget__content wysihtml-editor-content\" itemscope itemtype=\"https://schema.org/WebPage\">\n      <span class=\"js-text-content content-block\" itemprop=\"mainContentOfPage\" itemscope itemtype=\"https://schema.org/WebPageElement\">\n\n                    <div style=\"text-align: center;\"><a href=\"http://debat.verdensbilledet.dk/666.jpg\" target=\"_blank\"><img alt=\"666jpg\" src=\"/assets/edce1beeff523ef01876.jpg\" width=\"564\" height=\"618\"></a></div><div style=\"text-align: center;\"><span class=\"wysiwyg-font-size-12\"><b><span class=\"wysiwyg-color\" style=\"color: rgb(255, 255, 255);\"><a href=\"http://debat.vorespolitikere.dk/