glinkjpeg\" src=\"/assets/df59a3c790db151714e6.jpeg\" width=\"991\" height=\"123\"><br></a></div><div style=\"text-align: center;\"><a href=\"https://verdensbilledet.dk/universet#evangeliet\" target=\"_blank\"><b><span class=\"wysiwyg-font-size-10\">Det Nye Testamente, Hebræerbrevet, Kapitel 9:</span></b><span class=\"wysiwyg-font-size-12\"><br></span><b><span class=\"wysiwyg-font-size-10\">\"Derfor er Kristus formidler af en ny pagt, for at de kaldede kan få den evige arv, der er lovet, ved at han er død til forløsning fra overtrædelserne under den første pagt. For hvor der er et testamente, er det nødvendigt, at testators død godtgøres; et testamente får jo først betydning ved dødsfald, da det ikke har nogen som helst virkning, så længe han, som oprettede det, lever &gt;&gt;&gt;</span></b></a><br></div>\n          \n      </span>\n    </div>\n\n    \n\n</div>"},{"id":"s18","kind":"html","html":"<div id=\"page-zones__main-widgets__63a8e9b8e460e\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"whGUnH5HxYACzHg\" data-parentuniqueid=\"RLJB7nUxOF0aaIl\">\n        <div class=\"bk-content-text content widget__content wysihtml-editor-content\" itemscope itemtype=\"https://schema.org/WebPage\">\n      <span class=\"js-text-content content-block\" itemprop=\"mainContentOfPage\" itemscope itemtype=\"https://schema.org/WebPageElement\">\n\n                    <div style=\"text-align: center;\"><b><span class=\"wysiwyg-font-size-12\"><span style=\"color: rgb(255, 255, 255);\"><a href=\"https://mailform.dk/teamjesusdk\"><img alt=\"dvincipng\" src=\"/assets/0bb94c47b5aa9ec19775.png\" width=\"980\" height=\"189\"></a><br></span></span></b></div>\n          \n      </span>\n    </div>\n\n    \n\n</div>"},{"id":"s19","kind":"html","html":"<div id=\"page-zones__main-widgets__63d260a9012bf\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"wIEBOZSf1xLAVNB\" data-parentuniqueid=\"RLJB7nUxOF0aaIl\">\n    \n</div>