e\">\n      <span class=\"js-text-content content-block\" itemprop=\"mainContentOfPage\" itemscope itemtype=\"https://schema.org/WebPageElement\">\n\n                    \n\n<p style=\"text-align: center;\"><b><a href=\"https://mailform.dk/edn\" target=\"_blank\"><span class=\"wysiwyg-font-size-12\">Permakultur ''The garden of Eden'' &gt;&gt;&gt;</span></a><span class=\"wysiwyg-font-size-20\"><a href=\"https://mailform.dk/edn\" target=\"_blank\"><img alt=\"edenjpg\" src=\"/assets/90f3cb0417425c26b546.jpg\" width=\"993\" height=\"124\"></a></span></b><br></p>\n          \n      </span>\n    </div>\n\n    \n\n</div>"},{"id":"s46","kind":"html","html":"<div id=\"page-zones__main-widgets__63d2613453240\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"13Brp6Yl160Ypgl\" data-parentuniqueid=\"RLJB7nUxOF0aaIl\">\n    \n</div>"},{"id":"s47","kind":"html","html":"<div id=\"page-zones__main-widgets__601d61494f43b\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"oowAc8E9jQjNsU1\" data-parentuniqueid=\"RLJB7nUxOF0aaIl\">\n        <div class=\"bk-content-text content widget__content wysihtml-editor-content\" itemscope itemtype=\"https://schema.org/WebPage\">\n      <span class=\"js-text-content content-block\" itemprop=\"mainContentOfPage\" itemscope itemtype=\"https://schema.org/WebPageElement\">\n\n                    <div style=\"text-align: center;\"><b><span style=\"color: rgb(255, 255, 255);\"><span class=\"wysiwyg-font-size-14\">\"GUD BEVARE DANMARK er i vores statsministers mund blevet til GUD HAR VIGEPLIGT. Så en anden kan tage pladsen. Det ser vi med stor tydelighed, når man i den danske folkekirke og frikirker forlangte, at man skulle fremvise coronapas for at komme ind i GUDS HUS. Det harmonerer ikke med det kristne budskab om at elske sin næste, som sig selv. Vi er skabt i Guds billede med DNA som mennesker. Jeg foretrækker menneskelighed frem for mRNA skabt transhumanisme\" citat Lene Bang<br></span></span></b></div><div style=\"text-align: center;\"><b></b></div> <div style=\"text-align: center;\"><br></div><div style=\"text-align: center;\"><div style=\"text-align: center;\"><b><div style=\"text-align: center;\"><b><a href=\"https://udfordringen.dk/?s=konspirationsteorier\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">... og vedr de danske ''præster'' etc &gt;&gt;&gt;</span></a> <a href=\"https://mailform.dk/geert02\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">så pas på hvem I anklager for at være ''falske profeter''  &gt;&gt;&gt;</span></a><span class=\"wysiwyg-font-size-14\">&#160; </span><a href=\"https://mailform.dk/geert01\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">&gt;&gt;&gt;</span></a><span class=\"wysiwyg-font-size-14\">&#160; </span><a href=\"http://archive.mailform.dk/clt.pdf\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">&gt;&gt;&gt;</span></a><span class=\"wysiwyg-font-size-14\">&#160; </span><a href=\"https://verdensbilledet.dk/samfundsreligionen#co\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">&gt;&gt;&gt;</span></a><br></b></div><div style=\"text-align: center;\"><b><a href=\"https://verdensbilledet.dk/samfundsreligionen#666\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">i bestræbelsen på at være ''politisk korrekte'' under jeres afhængighed af ''systemernes'' ''tilbedelse'' af ''dyrets billede''  &gt;&gt;&gt;</span></a><span class=\"wysiwyg-font-size-14\">&#160; </span><a href=\"https://mailform.dk/trtlk01\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">&gt;&gt;&gt;</span></a></b></div><div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/bimtt225113\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">... og vedr ''tidens ånd'' så  fokuser på frihed til jeres sovende ''brude'' der i årtier kun har lært at følge mennesker og søge deres ''olie'' hos jer..? &gt;&gt;&gt;</span></a> <a href=\"http://archive.mailform.dk/letmypeoplego.mp3\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">&gt;&gt;&gt;</span></a><br></b></div><div style=\"text-align: center;\"><b><br></b></div><div style=\"text-align: center;\"><b><div style=\"text-align: center;\"><b><a href=\"http://archive.mailform.dk/mcd.mp3\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">Churchianity by Keith Green &gt;&gt;&gt;</span></a></b></div><div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/end001\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">The end of Churchianity &gt;&gt;&gt;</span></a></b></div><div style=\"text-align: center;\"><b><a href=\"https://mailform.dk/end002\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">The end of Churchianity 2 &gt;&gt;&gt;</span></a></b></div><div style=\"text-align: center;\"><b><a href=\"http://www.teamjesus.dk/1050.mp3\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">Gudsliv vs kirkeliv &gt;&gt;&gt;</span></a></b></div><div style=\"text-align: center;\"><b><a href=\"https://teamjesus.dk/hvemejerdig\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">Hvem ejer dig af Jon Knudsen &gt;&gt;&gt;</span></a></b></div><div style=\"text-align: center;\"><b><a href=\"http://teamjesus.dk/opraab\" target=\"_blank\"><span class=\"wysiwyg-font-size-14\">OPRÅB af Signe Valsøe &gt;&gt;&gt;</span></a><br></b></div></b></div></b></div><br></div>\n          \n      </span>\n    </div>\n\n    \n\n</div>"},{"id":"s48","kind":"html","html":"<div id=\"page-zones__main-widgets__63a67dab7c184\" data-name=\"content\" class=\"widget widget--zone-widget js-widget\" data-uniqueid=\"Y5oRRV2NJzi2ECc\" data-parentuniqueid=\"RLJB7nUxOF0aaIl\">\n        <div class=\"bk-content-text content widget__content wysihtml-editor-content\" itemscope itemtype=\"https://schema.org/WebPage\">\n      <span class=\"js-text-content content-block\" itemprop=\"mainContentOfPage\" itemscope itemtype=\"https://schema.org/WebPageElement\">\n\n                    <div style=\"text-align: center;\"><d